"""Top up question banks for the two CBSE Class 10 English Ch 1 chapters to reach 100 obj + 30-40 subj."""

from sqlalchemy import select
from app.db.session import SessionLocal
from app.models.curriculum import BloomLevel, LearningOutcome
from app.models.question import Question, QuestionDifficulty, QuestionStatus, QuestionType

CREATED_BY_ID = 14


def _options(q):
    return {"choices": list(q["options"])} if q.get("options") else None


def insert_for_chapter(db, chapter_id, supp):
    outcome_map = {r.code: r.id for r in db.scalars(
        select(LearningOutcome).where(LearningOutcome.chapter_id == chapter_id)).all()}
    existing = {r.text for r in db.scalars(
        select(Question).where(Question.chapter_id == chapter_id)).all()}
    added = 0
    for q in supp:
        if q["question"] in existing: continue
        oc = q.get("outcome_code")
        db.add(Question(
            chapter_id=chapter_id, topic_id=None,
            outcome_id=outcome_map.get(oc) if oc else None, outcome_code=oc,
            type=QuestionType(q["type"]), difficulty=QuestionDifficulty(q["difficulty"]),
            status=QuestionStatus.APPROVED,
            cognitive_level=BloomLevel(q["cognitive_level"].lower()),
            text=q["question"], options=_options(q), correct_answer=q["answer"],
            explanation=q.get("explanation"), marks=int(q.get("marks", 1)),
            created_by_id=CREATED_BY_ID))
        added += 1
    db.commit()
    return added


# ch219 — needs +14 subjective
EXTRA_219 = [
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-LTG-02","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"Why is rainfall so important to Lencho's family at the beginning of the story?","answer":"Lencho's family lives on a hillside farm in Mexico that DEPENDS ENTIRELY on the corn crop. The story opens with Lencho looking down at his field of grown corn dotted with the flowers that PROMISE A GOOD HARVEST — but the field needs ONE THING to bring the crop to fullness: a GOOD SHOWER OF RAIN. Without rain the harvest will fail and the family will starve. So the rain is not a luxury but a life-and-death matter; the family welcomes the first downpour as a sign of survival.","explanation":"Rain = survival."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-LTG-04","difficulty":"MEDIUM","cognitive_level":"ANALYZE","marks":3,"question":"What does the postmaster's response to the letter reveal about him as a person?","answer":"The postmaster is a 'fat, amiable fellow' whose first reaction to the letter is to LAUGH — at the simplicity of an envelope addressed to GOD. But he quickly TURNS SERIOUS. He decides he does NOT want to SHAKE Lencho's faith. He treats the letter SERIOUSLY, organises a collection from his employees, contributes part of his OWN salary, and signs the reply 'GOD'. His response reveals: (i) RESPECT for another's beliefs even when he doesn't share them; (ii) PRACTICAL COMPASSION — he doesn't just feel sorry for Lencho, he ACTS; (iii) GENEROSITY without expectation — he sends the money anonymously; (iv) HUMILITY — he is willing to make a small loss to preserve another man's faith. He is the moral centre of the story.","explanation":"Postmaster's character."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-LTG-06","difficulty":"MEDIUM","cognitive_level":"EVALUATE","marks":3,"question":"Was Lencho fair in his judgement of the post-office staff at the end of the story? Why or why not?","answer":"Lencho was NOT fair. His judgement is the central irony of the story — the very people who, moved by his faith, contributed their OWN money to help him, are accused by him of being 'a bunch of crooks'. He COULD NOT IMAGINE that ordinary people would have helped him; his world-view is so RIGID that any explanation other than divine intervention is unthinkable. So when the money comes short of the requested 100 pesos, his only available explanation is THEFT. The reader sees what Lencho cannot. His judgement reveals the danger of a faith so total that it cannot recognise human kindness; ironically, the very strength of his belief blinds him to the goodness of those around him.","explanation":"Unfair judgement."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-LTG-08","difficulty":"MEDIUM","cognitive_level":"EVALUATE","marks":3,"question":"What lessons can the modern reader draw from 'A Letter to God'?","answer":"Several lessons: (i) FAITH can be a source of strength but must be balanced with the ability to RECOGNISE HUMAN KINDNESS. (ii) HUMAN COMPASSION exists in unexpected places — even strangers, even people we dismiss with a laugh, can be moved to act. (iii) PERCEPTION matters as much as fact — Lencho cannot 'see' the human help; we too may misjudge those who help us. (iv) IRONY is built into life — we often misunderstand the very things that save us. (v) GENEROSITY DOES NOT NEED ACKNOWLEDGEMENT — the postmaster's kindness is its own reward, even when misjudged. (vi) Even the most religious person needs HUMILITY — the world has more good in it than any one world-view can capture.","explanation":"Modern lessons."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-LTG-07","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What is 'magical realism' and how does 'A Letter to God' fit the tradition?","answer":"MAGICAL REALISM is a Latin American literary tradition (associated with writers like Gabriel García Márquez, Jorge Luis Borges, Isabel Allende) in which the EVERYDAY mixes seamlessly with the MIRACULOUS. Realistic settings (a farm, a post office) host magical or supernatural events, presented in a matter-of-fact tone. 'A LETTER TO GOD' fits the tradition because it places a MIRACULOUS REQUEST (a letter posted to God) inside a perfectly REALISTIC setting (a small Mexican farm and a post office). Lencho's faith treats God as if He receives mail; the postmaster treats the letter as something that must be honoured. The tone is calm, almost folkloric. The READER is left to decide whether the answer was a miracle (God working through humans) or human compassion alone — the story holds the two together. This is the hallmark of magical realism.","explanation":"Magical realism."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-DOS-01","difficulty":"MEDIUM","cognitive_level":"UNDERSTAND","marks":3,"question":"Describe the tiny moment that 'Dust of Snow' captures.","answer":"The poem records ONE tiny moment in a winter day. The speaker is walking under a HEMLOCK TREE — a poisonous evergreen tree often associated with sadness in literature. A CROW lands on a branch above him. The crow's weight shakes the branch and DUSTS the speaker with snow — a fine fall of snowflakes, an accidental, unsought-for gift. That tiny moment of cold flakes from a 'dark' bird on a 'dark' tree somehow LIFTS THE SPEAKER'S MOOD. A part of the day he had been REGRETTING (he had 'rued' it) is suddenly SAVED. The whole poem is just this moment — eight lines, one sentence, one mood-change.","explanation":"The moment captured."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-DOS-02","difficulty":"MEDIUM","cognitive_level":"EVALUATE","marks":3,"question":"What does 'Dust of Snow' suggest about the role of NATURE in human life?","answer":"The poem suggests that NATURE is a quiet, often unnoticed HEALER. It does not always give grand sunsets or dramatic vistas — sometimes it gives a tiny, unsought-for moment that turns a 'rued' day into a SAVED one. The poem also suggests that the 'gloomy' parts of nature (a crow, a hemlock tree) are NOT WHAT THEY SEEM — even from dark sources, joy and renewal can come. Nature is generous in WAYS WE DON'T EXPECT and through CHANNELS we don't choose. To benefit from this gift, we have to be PRESENT — willing to notice what falls into our awareness rather than what we sought.","explanation":"Nature as quiet healer."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-DOS-03","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"List the key vocabulary of 'Dust of Snow' and give the meaning of each.","answer":"(i) HEMLOCK — a poisonous evergreen tree (in classical antiquity, the poison given to Socrates). (ii) RUED — past tense of 'rue': to feel regret about (a day, an action). (iii) DUST OF SNOW — a small, light fall of snowflakes shaken loose, like dust. (iv) BORE — past tense of 'bear': to carry. (v) Beyond these, the poem uses simple, everyday English: 'crow', 'snow', 'tree', 'change', 'mood', 'heart', 'day'. The simplicity of the vocabulary matches the simplicity of the moment; the difficulty is not in WORDS but in MEANING.","explanation":"Vocabulary."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-FAI-01","difficulty":"MEDIUM","cognitive_level":"REMEMBER","marks":3,"question":"What is the structure of 'Fire and Ice', and what kind of voice does it use?","answer":"'Fire and Ice' has NINE SHORT LINES. It uses an irregular but consistent rhyme scheme (roughly ABAABCBCB) — Frost rhymes 'fire/desire', 'ice/twice/suffice', 'great/hate'. The CONTRAST between fire and ice is the structural backbone: stanza-like halves built around the two destructive forces. The VOICE is conversational, almost casual — phrases like 'Some say', 'From what I've tasted', 'I think I know enough' make it feel as if the speaker is THINKING ALOUD, weighing the options. The tone is CALM and PHILOSOPHICAL — and that calmness, paired with the apocalyptic content, makes the poem more chilling, not less.","explanation":"Structure + voice."},
    {"type":"SHORT_ANSWER","outcome_code":"10-CBSE-ENG-FAI-03","difficulty":"MEDIUM","cognitive_level":"EVALUATE","marks":3,"question":"How does 'Fire and Ice' speak to the modern world?","answer":"Frost wrote 'Fire and Ice' in 1920, but its argument is more relevant than ever: (i) CLIMATE CHANGE is fire — driven by human DESIRE (consumption, growth at any cost). The world is heating up because of our refusal to limit our wants. (ii) WAR AND DIVISION are ice — driven by human HATE (ethnic, religious, national hatreds, slow-burning grudges). From the World Wars to today's conflicts, much destruction is the product of slow-frozen hate. (iii) PERSONAL LIFE — even at the smallest scale, our families and selves can be destroyed by uncontrolled DESIRE or accumulated HATE. The poem is a WARNING at every scale — global, civic, personal — and a CALL to control our own fire and ice before they end our world.","explanation":"Modern relevance."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-ENG-LTG-06","difficulty":"HARD","cognitive_level":"ANALYZE","marks":5,"question":"Compare Lencho with the postmaster in detail. What does each character represent?","answer":"LENCHO is a hard-working farmer of UNSHAKEABLE FAITH. After the hailstorm destroys his crop, he turns DIRECTLY to God — writing a letter for 100 pesos so he can plant his fields again. His faith is so simple and so TOTAL that he does not need a long address; 'To God' is enough. He is also DECISIVE and PRACTICAL — naming a specific amount with a specific purpose. But he is also STUBBORN and SUSPICIOUS — when only 70 pesos arrives, he immediately accuses the post office staff of theft. He CANNOT IMAGINE that ordinary humans would have helped him. WHAT HE REPRESENTS — Lencho stands for the SIMPLE, RIGID believer — strong in faith but blind to the human kindness that may answer prayers. He is also the EVERYMAN — his name is the familiar form of 'Lorenzo', and his story speaks to anyone with deep convictions. THE POSTMASTER is a 'fat, amiable fellow' whose first reaction is to LAUGH — but who quickly turns serious because he RESPECTS Lencho's faith. He is COMPASSIONATE in PRACTICE — he organises a collection, contributes from his own salary, and signs the reply 'God'. He acts ANONYMOUSLY, expecting no thanks. WHAT HE REPRESENTS — the postmaster stands for the QUIET, EVERYDAY HUMANIST — non-religious or differently religious, but capable of generous action across belief systems. He is the MORAL CENTRE of the story. CONTRAST — Lencho's goodness is INTERNAL (faith); the postmaster's is EXTERNAL (action). Tragically, Lencho cannot see that the postmaster's action is real goodness — and accuses him. The story uses the contrast to teach that BOTH kinds of goodness exist, and that neither alone is enough. We need both faith and the eyes to see the help that actually comes.","explanation":"Two characters compared."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-ENG-FAI-02","difficulty":"HARD","cognitive_level":"ANALYZE","marks":5,"question":"Discuss the symbolism of FIRE and ICE in Frost's poem. How effective is the symbolism?","answer":"Frost's poem hinges on a simple but powerful symbolic equation. FIRE = DESIRE. Fire is HOT, CONSUMING, ALL-OR-NOTHING. It burns what it touches and demands more fuel. Desire — lust, greed, ambition without limit — works the same way: it consumes the person, the family, the resources around it; it always wants more; it ends only when nothing is left to burn. ICE = HATE. Ice is COLD, SLOW, DEADENING. It does not destroy quickly; it freezes, cracks, kills slowly. Hate works the same way: it cools relationships, freezes compassion, hardens the heart, and outlasts the things that should have moved on. Slow but relentless. WHY THESE PARTICULAR SYMBOLS? Frost picks two NATURAL forces that are PHYSICALLY OPPOSITE (hot vs cold) yet BOTH DESTRUCTIVE. By linking them to human emotions, he shows that emotions can take many forms — explosive or freezing — yet do the same work of ENDING. The reader recognises both forces in their own life, in society, in history. EFFECTIVENESS — the symbolism is highly effective for several reasons. (i) IT IS UNIVERSAL — every reader knows fire, knows ice, knows desire, knows hate. (ii) IT IS SHORT AND VIVID — nine lines do the work that a sermon could not. (iii) IT REFUSES TO RANK — Frost does not say one is worse than the other, leaving the reader to ASK WHICH IS OPERATING IN THEIR OWN LIFE. (iv) IT BRIDGES PHYSICAL AND MORAL — natural disasters and human emotions are made parallel. (v) IT PERSISTS — the poem feels true a century after it was written, applying to climate change (fire/desire) and global conflict (ice/hate). Frost's symbolism is therefore one of the cleanest, most powerful uses of physical force as moral lesson in modern poetry.","explanation":"Symbolism analysed."},
    {"type":"LONG_ANSWER","outcome_code":"10-CBSE-ENG-DOS-02","difficulty":"HARD","cognitive_level":"EVALUATE","marks":5,"question":"How does Frost transform 'gloomy' symbols into vehicles of joy in 'Dust of Snow'? What does this teach us about reading?","answer":"Frost's poem performs a quiet but stunning REVERSAL. It opens with two symbols that, in Western literary and folk tradition, are usually negative: the CROW (associated with bad luck, sadness, sometimes death) and the HEMLOCK TREE (a POISONOUS evergreen — in classical antiquity the poison given to Socrates). A reader trained on traditional symbolism would expect a poem about doom. INSTEAD, Frost makes these dark symbols deliver JOY. The crow's accidental movement dusts the speaker with snow; that tiny gift LIFTS the speaker's mood and SAVES part of a 'rued' day. WHY DOES FROST DO THIS? Several reasons. (i) To show that NATURE is generous in unexpected ways — gifts can come from sources we have written off. (ii) To suggest that LIFE ITSELF is more complex than our symbolic categories — what we call 'gloomy' may carry blessings; what we call 'lucky' may bring ruin. (iii) To teach a quiet HUMILITY — we should look at the world with fresh eyes, not just inherited associations. (iv) To enact what the poem describes — just as the speaker's mood is unexpectedly lifted by a 'dark' source, the READER's expectations are unexpectedly reversed by 'dark' symbols. The form mirrors the content. WHAT IT TEACHES US ABOUT READING — (i) DON'T ASSUME a poem's symbols mean what tradition says they mean; check what the poem actually does with them. (ii) PAY ATTENTION TO REVERSALS — the poet's choice of dark symbols followed by a happy outcome is a deliberate signal. (iii) READ AT MULTIPLE LEVELS — the literal moment (snow, crow, mood) AND the symbolic point (gloom may carry joy). (iv) APPLY TO LIFE — outside the poem too, we should be ready for unexpected gifts from unlikely sources. The poem is, in this sense, both a moment of beauty and a lesson in attentiveness. Eight lines deliver more than they appear to.","explanation":"Reversal + reading."},
]

